mapper.select:
select date_format(create_time, #{format}) as bucket, scene as scene, model_name as modelName, count(*) as callCount, coalesce(sum(total_tokens), 0) as totalTokens, coalesce(sum(cost), 0) as totalCost, coalesce(round(avg(latency_ms)), 0) as avgLatencyMs from biz_ai_call_log where create_time >= #{start} and create_time < #{end}
and scene = #{scene}
group by bucket, scene, model_name order by bucket asc

select count(*) as totalCalls,
       coalesce(sum(case when cache_hit = 1 then 1 else 0 end), 0) as cacheHits
from biz_ai_call_log
where create_time >= #{start}
  and create_time < #{end}

  and scene = #{scene}
